#!/usr/bin/env python3
"""Build every generated file of this extension from the pinned sources.

Inputs: the Discovery document of the YouTube Data API v3 pinned in this folder
(youtube_v3.json), quota_costs.json
(extract_quota.py), names.py (titles, summaries, areas, exclusions), step_ids.json
(frozen step ids) and composite_specs.py (the everyday steps). Outputs:
runtime/registry.json, the four contract files, ui/actions/actions.yaml, the YouTube
API and Coverage pages, and extension.yaml. Run from the bundle root:

    python3 tests/reference/build_contracts.py

tests/test_contracts.py fails when a committed file differs from what this script
renders, so the files never drift from the sources.

A step id is written once to step_ids.json (``--new-ids`` adds ids for methods that
have none) and never derived again: titles may change, ids may not.
"""

from __future__ import annotations

import hashlib
import json
import re
import sys
from pathlib import Path
from typing import Any

