# -- UI pages ------------------------------------------------------------------------------

PAGE_IDS = {
    "Channels": "youtube-api-channels",
    "Videos": "youtube-api-videos",
    "Playlists": "youtube-api-playlists",
    "Comments and captions": "youtube-api-comments",
    "Live streaming": "youtube-api-live",
    "Subscriptions and regions": "youtube-api-subscriptions",
}


def step_text(row: dict[str, Any]) -> str:
    kind = "changes data in YouTube" if row["kind"] == "write" else "reads only"
    calls = ", ".join(f"`{c}`" for c in row["calls"])
    inputs = [f"`{i['name']}`" + (" (required)" if i["required"] else "") for i in row["inputs"]]
    lines = [
        f"### {row['title']}",
        "",
        row["description"],
        "",
        f"Action id `{row['id']}` · {kind} · YouTube: {calls}",
        "",
        "Inputs: " + (", ".join(inputs) if inputs else "none") + ".",
        "",
    ]
    if row["area"] == "Everyday":
        outputs = ", ".join(
            f"`{o['name']}`"
            for o in row["outputs"]
            if o["name"] not in {"external_effect_status", "definitely_no_external_effect"}
        )
        lines += ["Results: " + outputs + ".", ""]
    return "\n".join(lines)


def api_pages(rows: list[dict[str, Any]]) -> dict[str, dict[str, Any]]:
    pages: dict[str, dict[str, Any]] = {}
    total = len(rows)
    counts = {area: sum(1 for r in rows if r["area"] == area) for area in PAGE_IDS}
    overview = "\n".join(
        [
            "The steps call the YouTube Data API v3 for the connected channel. Every method of "
            f"the API that a step can hold has one: {total} steps in all, the everyday ones "
            "first. YouTube Analytics reports are in the separate extension "
            f"[{ANALYTICS_EXTENSION['name']}]({ANALYTICS_EXTENSION['url']}) "
            f"({ANALYTICS_EXTENSION['id']}).",
            "",
            "- **Scopes.** Each step names the Google scopes that allow it. The connection type "
            "decides which scopes are asked for: YouTube channel, YouTube channel with "
            "memberships, or YouTube content owner.",
            "- **Quota.** YouTube does not report the quota left in its answers. Each Data API "
            "step names its cost in quota units from YouTube's quota table; when the daily "
            "quota is used up, YouTube refuses with quotaExceeded and the step says so.",
            "- **Results.** A generated step returns `status`, `data` (YouTube's JSON) or `file` "
            "(a workflow file for a caption track), `etag` and `warnings`; a list also returns "
            "`items`, `count`, `complete` and `next_page_token`.",
            "- **Lists.** With `all_pages` a list step reads page after page; when it stops "
            "early, `next_page_token` is where the next run starts, so nothing is skipped or "
            "read twice.",
            "- **Request bodies** are the YouTube resource as JSON in `body`, with the parts "
            "named in `part`. A field the resource does not have is refused before sending.",
            "- **Accepted or completed.** Every step that changes data returns `processing`: "
            "`completed` when YouTube answered that the change is made, `accepted` for an "
            "uploaded video, which YouTube processes afterwards; then `applied` is false and "
            "`check` names Get video processing status.",
            "- **Changes are sent once.** A step that changes data is never retried "
            "automatically; when its outcome is unclear it says so, and you check YouTube "
            "before running it again. Test runs never send changes.",
            "",
            "The steps by area:",
            "",
            *[f"- **{area}** ({counts[area]} steps)" for area in PAGE_IDS],
        ]
    )
    everyday = "\n".join(step_text(r) for r in rows if r["area"] == "Everyday")
    pages["ui/pages/youtube-api.yaml"] = {
        "page_id": "youtube-api",
        "title": "YouTube API",
        "description": "How the YouTube steps work, and the everyday steps.",
        "components": [
            {
                "component_id": "api_overview",
                "type": "markdown",
                "title": "How the steps work",
                "body": overview + "\n",
            },
            {
                "component_id": "steps_everyday",
                "type": "markdown",
                "title": "Everyday",
                "body": everyday,
            },
        ],
    }
    for area, page_id in PAGE_IDS.items():
        area_rows = [r for r in rows if r["area"] == area]
        pages[f"ui/pages/{page_id}.yaml"] = {
            "page_id": page_id,
            "title": f"YouTube API: {area}",
            "description": f"The {len(area_rows)} {area.lower()} steps.",
            "components": [
                {
                    "component_id": "steps_" + snake(area),
                    "type": "markdown",
                    "title": area,
                    "body": "\n".join(step_text(r) for r in area_rows),
                }
            ],
        }
    return pages


def coverage_page(registry: dict[str, Any]) -> dict[str, Any]:
    ops = list(registry["operations"].values())
    total = len(ops)
    reads = sum(1 for e in ops if e["kind"] == "read")
    data_total = len(methods("data"))
    uploads = sum(1 for e in ops if (e["body"] or {}).get("upload"))
    paged = sum(1 for e in ops if e["pager"])
    with_cost = sum(1 for e in ops if e["api"] == "data" and e["quota"] is not None)
    sources = registry["sources"]
    excluded = "\n".join(
        f"- `{method_id}`: {reason}" for method_id, reason in registry["excluded"].items()
    )
    products = "\n".join(f"- **{name}**: {reason}" for name, reason in EXCLUDED_PRODUCTS.items())
    body = "\n".join(
        [
            f"The pinned Discovery document of the YouTube Data API v3 (revision "
            f"{sources['data']['revision']}, downloaded {sources['data']['downloaded']}) lists "
            f"{data_total} methods; **{total} of them have their own step** in this version.",
            "",
            f"- **{reads} reads** (GET) and **{total - reads} changes**. Test runs never send "
            "changes.",
            f"- **{paged} list steps** read all pages with `all_pages`; **{uploads} steps "
            "upload a file** by resumable upload; one saves a caption track as a file.",
            f"- **{with_cost} Data API steps** name their quota cost from YouTube's quota table "
            f"(updated {registry['quota_source']['last_updated']}).",
            "",
            "Methods without a step:",
            "",
            excluded,
            "",
            "Not in this release:",
            "",
            products,
            "",
            "The everyday steps on top: test the connection, get my channels, get all videos of "
            "a channel, get videos by ID, upload a video and follow its processing, update a "
            "video's details and thumbnail, get all comments of a video and reply, get and "
            "create playlists and add videos.",
        ]
    )
    return {
        "page_id": "coverage",
        "title": "Coverage",
        "description": "What of the YouTube Data API the steps offer.",
        "components": [
            {
                "component_id": "coverage_summary",
                "type": "markdown",
                "title": "Coverage",
                "body": body + "\n",
            }
        ],
    }


# -- output --------------------------------------------------------------------------------


def outputs() -> dict[str, Any]:
    ids = step_ids()
    missing = [
        m["id"] for _, m in all_methods() if m["id"] not in names.EXCLUDED and m["id"] not in ids
    ]
    if missing:
        raise SystemExit(f"no step id for {missing[:5]}; run with --new-ids")
    registry = build_registry(ids)
    rows = manifest_rows(registry)
    out: dict[str, Any] = {
        "runtime/registry.json": registry,
        "contracts/operation_manifest.yaml": operation_manifest(rows),
        "contracts/step_ui_manifest.yaml": step_ui_manifest(rows),
        "contracts/artifact_policies.yaml": artifact_policies(rows),
        "contracts/connection_types.yaml": connection_types(),
        "ui/actions/actions.yaml": actions_manifest(rows),
        "ui/pages/coverage.yaml": coverage_page(registry),
        "extension.yaml": extension_yaml(rows, registry),
    }
    out.update(api_pages(rows))
    return out


class _Dumper(yaml.SafeDumper):
    pass


def _str(dumper: yaml.SafeDumper, value: str) -> Any:
    style = "|" if "\n" in value else None
    return dumper.represent_scalar("tag:yaml.org,2002:str", value, style=style)


_Dumper.add_representer(str, _str)


def render(path: str, value: Any) -> str:
    if path.endswith(".json"):
        return json.dumps(value, ensure_ascii=False, indent=1, sort_keys=True) + "\n"
    if path == "extension.yaml":
        # The form `flow-steward extensions lock-deps` writes, so it changes nothing.
        return yaml.safe_dump(value, sort_keys=False, allow_unicode=True)
    return HEADER + yaml.dump(value, Dumper=_Dumper, sort_keys=False, allow_unicode=True, width=100)


def main(argv: list[str]) -> int:
    if "--new-ids" in argv:
        ids = step_ids()
        used = (
            set(ids.values())
            | {c["operation_id"] for c in composite_specs.COMPOSITES}
            | {"verify_identity"}
        )
        for _, m in all_methods():
            if m["id"] in names.EXCLUDED or m["id"] in ids:
                continue
            sid = new_step_id(names.TITLES[m["id"]][0])
            if sid in used:
                raise SystemExit(f"step id {sid} is taken")
            ids[m["id"]] = sid
            used.add(sid)
        STEP_IDS.write_text(json.dumps(ids, indent=1, sort_keys=True) + "\n", encoding="utf-8")
    rendered = outputs()
    for path, value in rendered.items():
        target = BUNDLE / path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(render(path, value), encoding="utf-8")
    print("generated", len(rendered), "files")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
